//! Acceptance test: replay every query in
//! src/test/data/platform/drive_query_vectors.json (generated by the
//! platform-drive-vectors crate from real dashpay/platform v4.0.0 + grovedb
//! v5.0.0 code) through the crate's verify_* functions. Passing proves that
//! the DriveDocumentQuery / contested-vote-poll constructions match the
//! query shapes the server executed, and that the proofs stay verifiable
//! across a platform minor-version bump (crate pins v4.1.0).
//!
//! Query parameters that are not carried in the vector file (DPNS labels,
//! limits) mirror src/test/platform_drive_tests.cpp.

use dash_platform_ffi::verify;
use serde::Deserialize;
use serde_json::Value;

#[derive(Deserialize)]
struct VectorFile {
    platform_repo_tag: String,
    identity_id: String,
    queries: Vec<QueryVector>,
}

#[derive(Deserialize)]
struct QueryVector {
    name: String,
    #[serde(default)]
    query: Value,
    grovedb_proof_hex: String,
    expected_root_hash_hex: String,
    expected: Value,
}

fn hexv(hex: &str) -> Vec<u8> {
    hex::decode(hex).expect("bad hex in test vector")
}

fn load() -> VectorFile {
    let file: VectorFile = serde_json::from_str(include_str!(
        "../../../src/test/data/platform/drive_query_vectors.json"
    ))
    .expect("parse drive_query_vectors.json");
    assert_eq!(file.platform_repo_tag, "v4.0.0");
    file
}

fn query<'a>(file: &'a VectorFile, name: &str) -> &'a QueryVector {
    file.queries
        .iter()
        .find(|query| query.name == name)
        .unwrap_or_else(|| panic!("query vector not found: {name}"))
}

#[test]
fn identity_balance() {
    let file = load();
    let q = query(&file, "identity_balance");
    let result = verify::verify_identity_balance(&hexv(&q.grovedb_proof_hex), &hexv(&file.identity_id))
        .expect("identity balance verify");
    assert_eq!(hex::encode(result.root_hash), q.expected_root_hash_hex);
    assert_eq!(result.value, q.expected["balance"].as_u64());
    assert!(result.value.is_some());
}

