#[test]
fn identity_keys() {
    use dpp::identity::identity_public_key::accessors::v0::IdentityPublicKeyGettersV0;
    use dpp::identity::IdentityPublicKey;
    use dpp::serialization::PlatformDeserializable;

    let file = load();
    let q = query(&file, "identity_keys");
    let result = verify::verify_identity_keys(&hexv(&q.grovedb_proof_hex), &hexv(&file.identity_id))
        .expect("identity keys verify");
    assert_eq!(hex::encode(result.root_hash), q.expected_root_hash_hex);
    let keys = result.keys.expect("identity proven present");

    let expected_keys: Vec<IdentityPublicKey> = q.expected["serialized_keys"]
        .as_array()
        .expect("serialized_keys")
        .iter()
        .map(|serialized| {
            IdentityPublicKey::deserialize_from_bytes(&hexv(serialized.as_str().unwrap()))
                .expect("expected key deserializes")
        })
        .collect();
    assert_eq!(keys.len(), expected_keys.len());
    for (key, expected) in keys.iter().zip(&expected_keys) {
        assert_eq!(key.id, expected.id());
        assert_eq!(key.purpose, expected.purpose() as u8);
        assert_eq!(key.security_level, expected.security_level() as u8);
        assert_eq!(key.key_type, expected.key_type() as u8);
        assert_eq!(key.read_only, expected.read_only());
        assert_eq!(key.data, expected.data().to_vec());
        assert_eq!(key.disabled_at, expected.disabled_at());
    }
    assert_eq!(
        keys.iter().map(|key| key.id).collect::<Vec<_>>(),
        vec![0, 1, 2]
    );
}

#[test]
fn identity_by_public_key_hash() {
    let file = load();
    {
        let q = query(&file, "identity_by_public_key_hash_present");
        let hash = hexv(q.query["public_key_hash"].as_str().expect("public_key_hash"));
        let result = verify::verify_identity_id_by_pubkey_hash(&hexv(&q.grovedb_proof_hex), &hash)
            .expect("identity by pubkey hash verify");
        assert_eq!(hex::encode(result.root_hash), q.expected_root_hash_hex);
        assert_eq!(
            result.id.map(hex::encode),
            q.expected["identity_id"].as_str().map(String::from)
        );
    }
    {
        let q = query(&file, "identity_by_public_key_hash_absent");
        let hash = hexv(q.query["public_key_hash"].as_str().expect("public_key_hash"));
        let result = verify::verify_identity_id_by_pubkey_hash(&hexv(&q.grovedb_proof_hex), &hash)
            .expect("identity by pubkey hash verify (absent)");
        assert_eq!(hex::encode(result.root_hash), q.expected_root_hash_hex);
        assert!(result.id.is_none(), "hash must be proven absent");
    }
}

fn check_documents(q: &QueryVector, result: dash_platform_ffi::types::DocsResult) {
    assert_eq!(
        hex::encode(result.root_hash),
        q.expected_root_hash_hex,
        "{}: root hash",
        q.name
    );
    let expected: Vec<String> = q.expected["documents"]
        .as_array()
        .expect("documents")
        .iter()
        .map(|document| document.as_str().unwrap().to_string())
        .collect();
    assert_eq!(
        result
            .documents
            .iter()
            .map(hex::encode)
            .collect::<Vec<_>>(),
        expected,
        "{}: documents",
        q.name
    );
}

