#[test]
fn dashpay_contacts() {
    let file = load();
    for (name, to_identity) in [
        ("dashpay_contacts_incoming", true),
        ("dashpay_contacts_outgoing", false),
    ] {
        let q = query(&file, name);
        let result = verify::verify_dashpay_contact_requests(
            &hexv(&q.grovedb_proof_hex),
            &hexv(&file.identity_id),
            to_identity,
            100,
        )
        .unwrap_or_else(|e| panic!("{name} verify: {e}"));
        check_documents(q, result);
    }
}

fn contested(file: &VectorFile, name: &str) -> (dash_platform_ffi::types::ContestedResult, Value) {
    let q = query(file, name);
    let label = q.query["normalized_label"].as_str().expect("normalized_label");
    let count = q.query["count"].as_u64().expect("count") as u16;
    let result = verify::verify_contested_vote_state(
        &hexv(&q.grovedb_proof_hex),
        &hexv("e668c659af66aee1e72c186dde7b5b7e0a1d712a09c40d5721f622bf53c53155"), // DPNS
        "domain",
        vec!["dash".to_string(), label.to_string()],
        count,
    )
    .unwrap_or_else(|e| panic!("{name} verify: {e}"));
    assert_eq!(
        hex::encode(result.root_hash),
        q.expected_root_hash_hex,
        "{name}: root hash"
    );
    (result, q.expected.clone())
}

#[test]
fn contested_vote_state_active() {
    let file = load();
    let (result, expected) = contested(&file, "contested_vote_state_active");
    let state = result.state;
    assert!(state.contest_found);
    assert!(!state.finished);
    assert!(!state.locked);
    assert!(state.winner.is_none());
    let expected_contenders = expected["contenders"].as_array().unwrap();
    assert_eq!(state.contenders.len(), expected_contenders.len());
    for ((identity, votes), expected) in state.contenders.iter().zip(expected_contenders) {
        assert_eq!(hex::encode(identity), expected["identity_id"].as_str().unwrap());
        assert_eq!(votes.map(u64::from), expected["votes"].as_u64());
    }
    assert_eq!(state.abstain_votes.map(u64::from), expected["abstain_votes"].as_u64());
    assert_eq!(state.lock_votes.map(u64::from), expected["lock_votes"].as_u64());
}

#[test]
fn contested_vote_state_finished() {
    let file = load();
    let (result, expected) = contested(&file, "contested_vote_state_finished");
    let state = result.state;
    assert!(state.contest_found);
    assert!(state.finished);
    assert!(!state.locked);
    assert_eq!(
        state.winner.map(hex::encode),
        expected["winner_identity_id"].as_str().map(String::from)
    );
    let expected_contenders = expected["contenders"].as_array().unwrap();
    assert_eq!(state.contenders.len(), expected_contenders.len());
    for ((identity, votes), expected) in state.contenders.iter().zip(expected_contenders) {
        assert_eq!(hex::encode(identity), expected["identity_id"].as_str().unwrap());
        assert_eq!(votes.map(u64::from), expected["votes"].as_u64());
    }
    assert_eq!(state.abstain_votes.map(u64::from), expected["abstain_votes"].as_u64());
    assert_eq!(state.lock_votes.map(u64::from), expected["lock_votes"].as_u64());
    assert!(state.finished_at_time_ms > 0);
}

#[test]
fn contested_vote_state_absent() {
    let file = load();
    let (result, _) = contested(&file, "contested_vote_state_absent");
    assert!(!result.state.contest_found);
    assert!(result.state.contenders.is_empty());
}

// A corrupted proof must never verify against the expected root.
#[test]
fn corrupted_proof_rejected() {
    let file = load();
    let q = query(&file, "identity_balance");
    let mut proof = hexv(&q.grovedb_proof_hex);
    let mid = proof.len() / 2;
    proof[mid] ^= 0x01;
    match verify::verify_identity_balance(&proof, &hexv(&file.identity_id)) {
        Err(_) => {}
        Ok(result) => {
            assert_ne!(
                hex::encode(result.root_hash),
                q.expected_root_hash_hex,
                "tampered proof must not reproduce the signed root"
            );
        }
    }
}
